import {AnyText} from "./model";
import {createContext, useContext, useState} from "react";

declare var requirejs: (deps: string[], callback: (module: any) => void, errback: (error: unknown) => void) => void;
type CoreStr = {
    getString: (identifier: string, component: string, a?: string | Record<string, unknown>) => Promise<string>,
}

const strPromise = new Promise<CoreStr>((resolve, reject) => {
    requirejs(['core/str'], resolve, () => reject("Could not load core/str"));
})

export const LanguageContext = createContext(["en"]);

export function Translated({text}: { text: AnyText }) {
    if (typeof text === "string") {
        return text;
    }

    if (typeof text === "object" && "identifier" in text && "component" in text) {
        const [string, setString] = useState(`${text.identifier}, ${text.component}`);
        strPromise
            .then(({getString}) => getString(text.identifier, text.component, text.a))
            .then(str => setString(str))
        return string;
    }

    const preferredLanguages = useContext(LanguageContext);

    for (const lang of preferredLanguages) {
        if (lang in text) {
            return text[lang];
        }
    }

    return Object.values(text)[0];
}